// bin/scaffold.mjs (extracto)
export function filesFor(template) {
  const base = ["demo.config.ts", "package.json"];
  const examples = ["pages/index.md", "pages/about.md", "pages/contact.md"];
  // TODO: minimal no debería llevar ejemplos
  if (template === "full" || template === "minimal") return [...base, ...examples];
  return base;
}
